/* Learning path: progress, lesson navigation and the path page. Data comes from assets/pathdata.js (generated by tools/build.py). */
(function () {
  "use strict";
  var D = window.MIBEM_PATHDATA, doc = document;
  if (!D) return;
  var LKEY = "mibem-lessons", DKEY = "mibem-days", SKEY = "mibem-solved";

  function load(k) { try { var v = JSON.parse(localStorage.getItem(k) || "[]"); return Array.isArray(v) ? v : []; } catch (e) { return []; } }
  function save(k, v) { try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) { /* storage unavailable: the path still works, without memory */ } }
  function esc(s) { return String(s).replace(/[&<>"']/g, function (c) { return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]; }); }
  function el(tag, cls, html) { var n = doc.createElement(tag); if (cls) n.className = cls; if (html != null) n.innerHTML = html; return n; }
  function today() { var d = new Date(); return d.getFullYear() + "-" + ("0" + (d.getMonth() + 1)).slice(-2) + "-" + ("0" + d.getDate()).slice(-2); }

  var done = load(LKEY);
  function key(u, l) { return u.slug + "#" + l.id; }
  function isDone(k) { return done.indexOf(k) >= 0; }
  function setDone(k, v) {
    var i = done.indexOf(k);
    if (v && i < 0) { done.push(k); var days = load(DKEY); if (days.indexOf(today()) < 0) { days.push(today()); save(DKEY, days); } }
    if (!v && i >= 0) done.splice(i, 1);
    save(LKEY, done);
  }

  /* flat list of every lesson that exists, in path order */
  var flat = [];
  D.forEach(function (sec, si) {
    sec.units.forEach(function (u) {
      u.lessons.forEach(function (l, li) { flat.push({ u: u, l: l, li: li, si: si, k: key(u, l) }); });
    });
  });
  function firstUndone() { for (var i = 0; i < flat.length; i++) if (!isDone(flat[i].k)) return flat[i]; return null; }
  function href(f, base) { return base + f.u.slug + ".html#" + f.l.id; }

  function streak() {
    var days = load(DKEY).sort(), n = 0, d = new Date();
    function fmt(x) { return x.getFullYear() + "-" + ("0" + (x.getMonth() + 1)).slice(-2) + "-" + ("0" + x.getDate()).slice(-2); }
    if (days.indexOf(fmt(d)) < 0) d.setDate(d.getDate() - 1);
    while (days.indexOf(fmt(d)) >= 0) { n++; d.setDate(d.getDate() - 1); }
    return n;
  }
  function xp() { return done.length * 10 + load(SKEY).length * 5; }

  /* ---------------- lesson navigation inside course pages ---------------- */
  function initLessons() {
    var slug = (location.pathname.match(/([^\/]+)\.html$/) || [])[1];
    if (!slug) return;
    var mine = flat.filter(function (f) { return f.u.slug === slug; });
    if (!mine.length) return;
    var article = doc.querySelector("article");
    if (!article) return;
    var total = flat.length;
    mine.forEach(function (f, idx) {
      var h = doc.getElementById(f.l.id);
      if (!h) return;
      var next = mine[idx + 1], stop = next ? doc.getElementById(next.l.id) : doc.getElementById("refs");
      if (!stop) stop = article.querySelector("nav.pager");
      var gi = flat.indexOf(f), prevF = flat[gi - 1], nextF = flat[gi + 1];
      var box = el("div", "lesson-nav");
      box.setAttribute("role", "group");
      box.setAttribute("aria-label", "Lesson navigation");
      function render() {
        var d = isDone(f.k), pct = Math.round(100 * done.length / total);
        var nextLabel = nextF ? (nextF.u === f.u ? "Next lesson: " + esc(nextF.l.t) : "Next course: " + esc(nextF.u.code) + " " + esc(nextF.u.title)) : "Back to the path";
        var nextHref = nextF ? (nextF.u === f.u ? "#" + nextF.l.id : href(nextF, "")) : "../path.html";
        box.innerHTML =
          '<div class="ln-top"><span class="ln-pos">' + esc(f.u.code) + " &middot; lesson " + (f.li + 1) + " of " + f.u.lessons.length + '</span>' +
          '<span class="ln-xp">' + xp() + ' XP</span></div>' +
          '<div class="ln-bar" role="img" aria-label="' + pct + '% of the whole path complete"><i style="width:' + pct + '%"></i></div>' +
          '<div class="ln-actions">' +
          (prevF ? '<a class="btn ghost" href="' + (prevF.u === f.u ? "#" + prevF.l.id : href(prevF, "")) + '">&larr; Previous</a>' : '<a class="btn ghost" href="../path.html">Learning path</a>') +
          '<button type="button" class="btn ln-done' + (d ? " is-done" : "") + '">' + (d ? "&#10003; Completed. Mark as not done" : "Complete this lesson (+10 XP)") + "</button>" +
          '<a class="btn ln-next" href="' + nextHref + '">' + nextLabel + " &rarr;</a></div>";
        box.querySelector(".ln-done").addEventListener("click", function () { setDone(f.k, !isDone(f.k)); document.querySelectorAll(".lesson-nav").forEach(function (b) { b._render && b._render(); }); updateTocTicks(); });
        box.querySelector(".ln-next").addEventListener("click", function () { if (!isDone(f.k)) { setDone(f.k, true); updateTocTicks(); } });
      }
      box._render = render; render();
      stop.parentNode.insertBefore(box, stop);
    });
    updateTocTicks();
    function updateTocTicks() {
      mine.forEach(function (f) {
        var a = doc.querySelector('.toc a[href="#' + f.l.id + '"]');
        if (a) a.classList.toggle("lesson-done", isDone(f.k));
      });
    }
  }

  /* ---------------- the path page ---------------- */
  function initPath() {
    var host = doc.getElementById("learn-path");
    if (!host) return;
    function draw() {
      host.innerHTML = "";
      var cur = firstUndone(), total = flat.length;
      var stats = el("div", "lp-stats");
      stats.innerHTML =
        '<div><b>' + streak() + '</b><span>day streak</span></div><div><b>' + xp() + '</b><span>XP</span></div>' +
        '<div><b>' + done.length + "/" + total + '</b><span>lessons done</span></div>' +
        '<div class="lp-cta">' + (cur ? '<a class="btn" href="' + href(cur, "computational/") + '">' + (done.length ? "Continue" : "Start learning") + ": " + esc(cur.u.code) + "</a>" : "<b>Everything available is complete.</b>") + "</div>";
      host.appendChild(stats);
      D.forEach(function (sec, si) {
        var banner = el("div", "lp-section s" + (si % 6));
        banner.innerHTML = "<h2>" + esc(sec.name) + "</h2><p>" + esc(sec.sub) + "</p>";
        host.appendChild(banner);
        sec.units.forEach(function (u) {
          var n = u.lessons.length, d = u.lessons.filter(function (l) { return isDone(key(u, l)); }).length;
          var unit = el("section", "lp-unit" + (u.slug ? "" : " locked") + (n && d === n ? " complete" : ""));
          var needs = u.needs.length ? "Needs " + u.needs.map(function (c) { return esc(c); }).join(", ") : "No prerequisites";
          var head = el("div", "lp-uhead");
          head.innerHTML = '<div><span class="lp-code">' + esc(u.code) + "</span><h3>" + (u.slug ? '<a href="computational/' + u.slug + '.html">' + esc(u.title) + "</a>" : esc(u.title) + " (in preparation)") + "</h3>" +
            '<p class="lp-blurb">' + esc(u.blurb) + '</p><p class="lp-meta">' + needs + (u.slug ? " &middot; " + d + "/" + n + " lessons &middot; about " + u.min + " min of reading" : "") + "</p></div>" +
            (u.slug ? '<button type="button" class="lp-know">I know this</button>' : '<span class="lp-lock" aria-hidden="true">&#128274;</span>');
          unit.appendChild(head);
          if (u.slug) {
            head.querySelector(".lp-know").addEventListener("click", function () { u.lessons.forEach(function (l) { setDone(key(u, l), true); }); draw(); });
            var trail = el("ol", "lp-trail");
            u.lessons.forEach(function (l, li) {
              var k = key(u, l), isCur = cur && cur.k === k, st = isDone(k) ? "done" : isCur ? "current" : "todo";
              var li_ = el("li", "lp-node " + st + " p" + (li % 4));
              var kind = l.id === "check" ? "P" : l.id === "quiz" ? "Q" : String(li + 1);
              li_.innerHTML = '<a href="computational/' + u.slug + ".html#" + l.id + '" title="' + esc(l.t) + '" aria-label="' + esc(l.t) + (st === "done" ? " (completed)" : isCur ? " (next)" : "") + '"><span class="lp-dot">' + (st === "done" ? "&#10003;" : kind) + "</span></a><span class=\"lp-label\">" + esc(l.t.replace(/^Lecture \d+\.\s*/, "")) + "</span>" + (isCur ? '<span class="lp-here">Start</span>' : "");
              trail.appendChild(li_);
            });
            unit.appendChild(trail);
          }
          host.appendChild(unit);
        });
      });
      var c = host.querySelector(".lp-node.current");
      if (c && !draw.scrolled) { draw.scrolled = true; /* do not steal the scroll position unless asked */ }
    }
    draw();
  }

  function init() { initLessons(); initPath(); }
  if (doc.readyState === "loading") doc.addEventListener("DOMContentLoaded", init); else init();
})();
